            ..close();
        });

        final source = await HttpServer.bindSecure(
          InternetAddress.loopbackIPv4,
          0,
          tlsContext,
        );
        source.listen((request) async {
          await utf8.decoder.bind(request).join();
          request.response
            ..statusCode = 308
            ..headers.set('Location', 'http://127.0.0.1:${target.port}/landed')
            ..close();
        });

        try {
          final transport = TransportOptionsBuilder().verifySsl(false).build();
          final client = DefaultApiClient(transportOptions: transport);
          await expectLater(
            client.sendRequest(
              'POST',
              'https://127.0.0.1:${source.port}/secret',
              {'Content-Type': 'application/x-www-form-urlencoded'},
              Uint8List.fromList(utf8.encode('client_secret=hunter2')),
            ),
            throwsA(
              isA<ApiException>()
                  .having((e) => e.runtimeType, 'runtimeType', ApiException)
                  .having(
                    (e) => e.statusCode,
                    'statusCode',
                    inInclusiveRange(307, 308),
                  )
                  .having(
                    (e) => e.message,
                    'message',
                    contains('HTTPS->HTTP redirect'),
                  ),
            ),
          );
          expect(
            targetHits,
            equals(0),
            reason:
                '308 downgrade with a body must not contact the '
                'plain-HTTP target',
          );
        } finally {
          await source.close();
          await target.close();
        }
      },
    );

    // T-new-3: multipart bodies must be replayed across 307 redirects per
    // RFC 7231 §6.4.7 / RFC 7538. Regression test: ensure the follow-up
    // request after a 307 still carries the multipart form parts.
    test(
      'bhv retries 012 replays multipart body across 307 redirects (T-new-3)',
      () async {
        final transport = TransportOptionsBuilder()
            .followRedirects(true)
            .maxRedirects(5)
            .build();
        final client = DefaultApiClient(transportOptions: transport);
        const boundary = 'test-boundary';
        final body =
            '--$boundary\r\n'
            'Content-Disposition: form-data; name="description"\r\n\r\n'
            'hello\r\n'
            '--$boundary\r\n'
            'Content-Disposition: form-data; name="file"; filename="file"\r\n'
            'Content-Type: application/octet-stream\r\n\r\n'
            'file-content-bytes\r\n'
            '--$boundary--\r\n';
        /* chasm replays the 307 redirect to its echo endpoint; the echo
       envelope's method+body confirm the multipart body arrived intact
       at the redirect target. */
        final resp = await client.sendRequest(
          'POST',
          '$chasmHttpUrl/test/redirect/307-multipart',
          {'Content-Type': 'multipart/form-data; boundary=$boundary'},
          body,
        );
        expect(resp.statusCode, equals(200));
        final parsed = jsonDecode(resp.body) as Map<String, dynamic>;
        expect(parsed['method'], equals('POST'));
        expect(
          parsed['body'],
          isNotEmpty,
          reason:
              'multipart body must be replayed intact across the 307 redirect',
        );
      },
    );

    test('bhv redirects 006 respects maxRedirects limit', () async {
      final transport = TransportOptionsBuilder()
          .followRedirects(true)
          .maxRedirects(2)
          .build();
      expect(transport.maxRedirects, equals(2));
      final client = DefaultApiClient(transportOptions: transport);
      expect(client, isNotNull);
    });

    // Wave E: redirect counting must be scoped to a SINGLE request, not
    // shared on the client/transport. The Dart transport keeps its hop
    // counter as a local variable inside `sendRequest`, so each call is
    // independent. This test would catch a regression that hoisted the
    // counter (or the too-many-redirects refusal) onto the client: fire
    // many requests CONCURRENTLY through ONE shared client with
    // maxRedirects(1) — each `/test/redirect/302` is exactly one hop and
    // must succeed. If the hop counter were shared, the overlapping
    // in-flight redirects would inflate it past 1 and trip the limit on
    // some requests; with per-request scoping every request gets 200,
    // and a non-redirecting request mixed in is unaffected.
    test(
      'bhv redirects 003 concurrent redirects do not share a hop counter (Wave E)',
      () async {
        final transport = TransportOptionsBuilder()
            .followRedirects(true)
            .maxRedirects(1)
            .build();
        final client = DefaultApiClient(transportOptions: transport);
        try {
          final futures = <Future<int>>[
            // A non-redirecting request sharing the same client. Its outcome
            // must not be disturbed by the concurrent redirect traffic.
            client
                .sendRequest('GET', '$chasmHttpUrl/test/echo', {}, null)
                .then((r) => r.statusCode),
            // Several single-hop redirects fired together. Each consumes one
            // hop; none should see another request's hop charged against it.
            for (var i = 0; i < 8; i++)
              client
                  .sendRequest(
                    'GET',
                    '$chasmHttpUrl/test/redirect/302',
                    {},
                    null,
                  )
                  .then((r) => r.statusCode),
          ];
          final codes = await Future.wait(futures);
          expect(
            codes,
            everyElement(equals(200)),
            reason:
                'each concurrent request must follow its own redirect '
                'chain within the per-request hop budget; a shared counter '
                'would trip the maxRedirects(1) limit on some of them',
          );
        } finally {
          client.close();
        }
      },
    );

    // Wave E: a too-many-redirects refusal raised by ONE request must not
    // surface on an unrelated CONCURRENT request through the same client.
    // With maxRedirects(0) any single-hop redirect legitimately fails with
    // the typed limit error, while a non-redirecting request must still
    // succeed — proving the refusal is scoped to the offending request and
    // not stored on a shared error slot.
    test(
      'bhv langdart 039 a too-many-redirects refusal stays on its own request (Wave E)',
      () async {
        final transport = TransportOptionsBuilder()
            .followRedirects(true)
            .maxRedirects(0)
            .build();
        final client = DefaultApiClient(transportOptions: transport);
        try {
          final okFuture = client.sendRequest(
            'GET',
            '$chasmHttpUrl/test/echo',
            {},
            null,
          );
          final refusedFuture = client.sendRequest(
            'GET',
            '$chasmHttpUrl/test/redirect/302',
            {},
            null,
          );

          // The redirecting request hits the zero-hop limit and refuses.
          await expectLater(
            refusedFuture,
            throwsA(
              isA<ApiException>()
                  .having((e) => e.runtimeType, 'runtimeType', ApiException)
                  .having((e) => e.statusCode, 'statusCode', 302)
                  .having((e) => e.message, 'message', contains('redirect')),
            ),
          );
          // The concurrent non-redirecting request is unaffected by the
          // other request's refusal and completes normally.
          final ok = await okFuture;
          expect(
            ok.statusCode,
            equals(200),
            reason:
                'a refusal on one request must not surface on another '
                'sharing the same client',
          );
        } finally {
          client.close();
        }
      },
    );

    test('bhv serializationwire 027 sends multipart form data', () async {
      final client = DefaultApiClient();
      final headers = {
        'Content-Type': 'multipart/form-data; boundary=test-boundary',
      };
      final body =
          '--test-boundary\r\nContent-Disposition: form-data; name="description"\r\n\r\nA test file\r\n--test-boundary--\r\n';
      final resp = await client.sendRequest(
        'POST',
        '$chasmHttpUrl/test/echo',
        headers,
        body,
      );
      expect(resp, isNotNull);
    });

    // W-new-2: multipart field name validation must run on every branch, not
    // just the Uint8List path. Previously the String/num/bool and JSON
    // branches injected the raw field name into Content-Disposition, opening
    // a header-smuggling hole. This test uses a String value so it exercises
    // the non-binary branch.
    test(
      'bhv serializationwire 026 multipart_field_name_with_crlf_rejected_on_string_value',
      () async {
        final client = DefaultApiClient();
        final badField = <String, Object?>{'name\r\nInjected: yes': 'value'};
        expect(
          () => client.sendRequest(
            'POST',
            '$chasmHttpUrl/test/echo',
            {},
            badField,
          ),
          throwsArgumentError,
        );
      },
    );

    test('bhv transport 005 decompresses gzip response', () async {
      final client = DefaultApiClient();
      final resp = await client.sendRequest(
        'GET',
        '$chasmHttpUrl/test/compressed/gzip',
        {'Accept-Encoding': 'gzip'},
        null,
      );
      expect(resp.statusCode, equals(200));
      expect(resp.body, contains('compressed fixture body'));
    });

    for (final coding in ['br', 'zstd']) {
      test(
        'bhv langdart 040 refuses a $coding response it cannot decode',
        () async {
          final client = DefaultApiClient();
          await expectLater(
            client.sendRequest('GET', '$chasmHttpUrl/test/compressed/$coding', {
              'Accept-Encoding': coding,
            }, null),
            throwsA(
              isA<ApiException>()
                  .having((e) => e.statusCode, 'statusCode', 200)
                  .having(
                    (e) => e.message,
                    'message',
                    equals("Unsupported Content-Encoding '$coding'"),
                  ),
            ),
          );
        },
      );
    }

    test(
      'bhv transport 010 includes transport default headers from a map',
      () async {
        final transport = TransportOptionsBuilder().defaultHeaders({
          'X-Map-Header': 'map-value',
        }).build();
        final client = DefaultApiClient(transportOptions: transport);
        final resp = await client.sendRequest(
          'GET',
          '$chasmHttpUrl/test/echo',
          {},
          null,
        );
        final parsed = jsonDecode(resp.body) as Map<String, dynamic>;
        final headers = parsed['headers'] as Map<String, dynamic>;
        expect(headers['x-map-header'], equals('map-value'));
      },
    );

    test('bhv transport 013 injects request id header', () async {
      final transport = TransportOptionsBuilder().injectRequestId(true).build();
      final client = DefaultApiClient(transportOptions: transport);
      final resp = await client.sendRequest(
        'GET',
        '$chasmHttpUrl/test/echo',
        {},
        null,
      );
      final parsed = jsonDecode(resp.body) as Map<String, dynamic>;
      final headers = parsed['headers'] as Map<String, dynamic>;
      expect(headers.containsKey('x-request-id'), isTrue);
    });

    test(
      'bhv transport 007 generates unique request ids across three requests',
      () async {
        final transport = TransportOptionsBuilder()
            .injectRequestId(true)
            .build();
        final client = DefaultApiClient(transportOptions: transport);
        final ids = <Object?>{};

        for (var i = 0; i < 3; i++) {
          final resp = await client.sendRequest(
            'GET',
            '$chasmHttpUrl/test/echo',
            {},
            null,
          );
          final parsed = jsonDecode(resp.body) as Map<String, dynamic>;
          final headers = parsed['headers'] as Map<String, dynamic>;
          ids.add(headers['x-request-id']);
        }

        expect(ids.length, equals(3));
      },
    );

    test(
      'bhv transport 046 leaves the proxy auth header null when no proxy is configured',
      () {
        final client = DefaultApiClient();
        expect(client.proxyAuthHeader, isNull);
      },
    );

    test(
      'bhv transport 023 the default transport rejects a certificate from an untrusted CA',
      () async {
        final client = DefaultApiClient();
        await expectLater(
          client.sendRequest('GET', '$chasmHttpsUrl/test/echo', {}, null),
          throwsA(
            isA<NetworkException>()
                .having((e) => e.statusCode, 'statusCode', 0)
                .having((e) => e.cause, 'cause', isA<TlsException>()),
          ),
        );
      },
    );

    test(
      'bhv transport 025 verifySsl=true rejects a certificate the system does not trust',
      () async {
        final transport = TransportOptionsBuilder().verifySsl(true).build();
        final client = DefaultApiClient(transportOptions: transport);
        await expectLater(
          client.sendRequest('GET', '$chasmHttpsUrl/test/echo', {}, null),
          throwsA(
            isA<NetworkException>()
                .having((e) => e.statusCode, 'statusCode', 0)
                .having((e) => e.cause, 'cause', isA<TlsException>()),
          ),
        );
      },
    );

    // Regression: POST/PUT/PATCH with body == null must emit an
    // explicit Content-Length: 0. Some servers / WAFs reject body-
    // bearing verbs with no Content-Length (411 Length Required). The
    // client attaches an empty Uint8List on body-bearing verbs so
    // dart:http emits the header.
    test(
      'bhv transport 019 post_with_null_body_sends_content_length_zero',
      () async {
        final client = DefaultApiClient();
        final resp = await client.sendRequest(
          'POST',
          '$chasmHttpUrl/test/echo',
          {},
          null,
        );
        expect(resp.statusCode, equals(200));
        final parsed = jsonDecode(resp.body) as Map<String, dynamic>;
        expect(
          parsed['contentLength'],
          equals(0),
          reason: 'POST with null body must emit Content-Length: 0',
        );
      },
    );

    // Gap T6: close() releases the underlying HTTP client and is
    // idempotent. A request issued on a closed client must surface a
    // uniform SDK error (ApiException) rather than the dart:http package's
    // "Client is already closed" exception.
    test('bhv lifecycle 018 close releases underlying client', () async {
      final client = DefaultApiClient();
      client.close();
      // close() is idempotent.
      client.close();
      // Use after close is a wrong call order: the invalid-state StateError.
      expect(
        () => client.sendRequest('GET', 'https://example.com', {}, null),
        throwsA(isA<StateError>()),
      );
    });
  });
}
